function verifyBackupEnvelope(envelope){if(!envelope||typeof envelope!=='object'||!envelope.data||typeof envelope.data!=='object'||Array.isArray(envelope.data))return {valid:false,reason:'INVALID_DATA'};const m=envelope.manifest;if(!m||m.format!=='houshak-json-backup'||m.formatVersion!==1||typeof m.sha256!=='string')return {valid:false,reason:'INVALID_MANIFEST'};const serialized=JSON.stringify(envelope.data),digest=crypto.createHash('sha256').update(serialized).digest('hex'),bytes=Buffer.byteLength(serialized,'utf8');if(digest!==m.sha256)return {valid:false,reason:'HASH_MISMATCH',expectedHash:m.sha256,actualHash:digest};if(Number(m.bytes)!==bytes)return {valid:false,reason:'SIZE_MISMATCH',expectedBytes:m.bytes,actualBytes:bytes};const actualCounts={};for(const [key,value] of Object.entries(envelope.data))if(Array.isArray(value))actualCounts[key]=value.length;if(JSON.stringify(actualCounts)!==JSON.stringify(m.collectionCounts||{}))return {valid:false,reason:'COLLECTION_COUNTS_MISMATCH',actualCounts};return {valid:true,appVersion:m.appVersion||envelope.version||null,generatedAt:m.generatedAt||envelope.exportedAt||null,bytes,sha256:digest,collectionCounts:actualCounts}}
