function inspectBackupForRestore(envelope){const integrity=verifyBackupEnvelope(envelope);if(!integrity.valid)return {...integrity,restorable:false,errors:[integrity.reason],warnings:[]};const data=envelope.data,errors=[],warnings=[];for(const key of backupRequiredCollections)if(!Array.isArray(data[key]))errors.push(`COLLECTION_INVALID:${key}`);if(errors.length)return {...integrity,valid:false,restorable:false,errors,warnings};for(const key of ['users','owners','yards','categories','assets','reservations','contracts','invoices','transactions']){const seen=new Set();for(const row of data[key]){if(!row||typeof row!=='object'||Array.isArray(row)){errors.push(`ROW_INVALID:${key}`);continue}if(row.id!==undefined){if(seen.has(String(row.id)))errors.push(`DUPLICATE_ID:${key}:${row.id}`);seen.add(String(row.id))}}}const assetIds=new Set(data.assets.map(x=>String(x?.id))),reservationIds=new Set(data.reservations.map(x=>String(x?.id))),contractIds=new Set(data.contracts.map(x=>String(x?.id))),invoiceIds=new Set(data.invoices.map(x=>String(x?.id)));for(const r of data.reservations)if(r?.assetId&&!assetIds.has(String(r.assetId)))warnings.push(`MISSING_ASSET_REFERENCE:reservations:${r.id}`);for(const c of data.contracts)if(c?.assetId&&!assetIds.has(String(c.assetId)))warnings.push(`MISSING_ASSET_REFERENCE:contracts:${c.id}`);for(const i of data.invoices){if(i?.assetId&&!assetIds.has(String(i.assetId)))warnings.push(`MISSING_ASSET_REFERENCE:invoices:${i.id}`);if(i?.reservationId&&!reservationIds.has(String(i.reservationId)))warnings.push(`MISSING_RESERVATION_REFERENCE:invoices:${i.id}`);if(i?.contractId&&!contractIds.has(String(i.contractId)))warnings.push(`MISSING_CONTRACT_REFERENCE:invoices:${i.id}`);const total=Number(i?.total??i?.subtotal??0),paid=Number(i?.paid||0),balance=Number(i?.balance??(total-paid));if(!Number.isFinite(total)||!Number.isFinite(paid)||!Number.isFinite(balance)||total<0||paid<0||paid>total+0.009||Math.abs(balance-(total-paid))>0.009)warnings.push(`INVOICE_FINANCIAL_MISMATCH:${i?.id??'unknown'}`)}for(const t of data.transactions){const amount=Number(t?.amount);if(!['INCOME','EXPENSE'].includes(t?.type)||!Number.isFinite(amount)||amount<=0)warnings.push(`TRANSACTION_INVALID_FINANCIAL_ROW:${t?.id??'unknown'}`);if(t?.invoiceId&&!invoiceIds.has(String(t.invoiceId)))warnings.push(`MISSING_INVOICE_REFERENCE:transactions:${t.id}`)}return {...integrity,valid:errors.length===0,restorable:errors.length===0,errors,warnings,previewOnly:true,notice:'هذه معاينة تحقق فقط؛ لم تُستعد البيانات. سُجلت عملية الفحص في سجل التدقيق. التحذيرات المالية والمرجعية تتطلب مراجعة ولا تُعدّل البيانات تلقائيًا.'}}
