function cleanIdentityImage(value,label){if(value===undefined||value===null||value==='')return '';if(typeof value!=='string'||value.length>1_500_000)throw new Error(`صورة ${label} كبيرة جدًا؛ اختر صورة أصغر من 1 ميغابايت تقريبًا`);if(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value))throw new Error(`صيغة صورة ${label} غير مدعومة؛ استخدم JPG أو PNG أو WEBP`);return value}
