function audit(u,action,entity,entityId,details={}){db.auditLogs.push({id:id('audit'),userId:u?.id||null,actorName:u?.name||'النظام',actorRole:u?.role||'SYSTEM',action,entity,entityId,details,createdAt:now()})}
function recalculateCurrentBid(assetId){const a=asset(assetId);if(!a)return;const valid=db.offers.filter(o=>o.assetId===assetId&&o.status==='OPEN'&&Number.isFinite(Number(o.amount))&&Number(o.amount)>0).sort((x,y)=>Number(y.amount)-Number(x.amount)||new Date(y.updatedAt||y.createdAt)-new Date(x.updatedAt||x.createdAt));a.currentBid=valid.length?Number(valid[0].amount):null;a.currentBidAt=valid.length?(valid[0].updatedAt||valid[0].createdAt||now()):null;}
function notify(userId,title,message,type='INFO'){if(!userId)return;db.notifications.push({id:id('not'),userId,title,message,type,read:false,createdAt:now()})}
function deriveVisibility(purpose,status,override='AUTO'){if(['RESERVED','SOLD','RENTED','EXITED'].includes(status))return false;if(override==='HIDE')return false;if(override==='SHOW')return status==='ACTIVE';return ['SALE','RENT','SALE_RENT'].includes(purpose)&&status==='ACTIVE'}
export {deriveVisibility, categoryFieldDefaults};
function refreshVisibility(a){a.publicVisible=deriveVisibility(a.purpose,a.status,a.publishOverride||'AUTO');return a}
function addHistory(a,u,old,note){db.history.push({id:id('hist'),assetId:a.id,fromPurpose:old?.purpose??null,toPurpose:a.purpose,fromStatus:old?.status??null,toStatus:a.status,note,changedById:u?.id||null,createdAt:now()})}
function activeStorage(a){return db.storageCharges.find(c=>c.assetId===a.id&&!c.toAt)}
function storageAccrued(a){const c=activeStorage(a);if(!c)return {days:0,current:0,charge:null};const from=new Date(c.fromAt).getTime();const end=a.exitAt?new Date(a.exitAt).getTime():Date.now();const days=Math.max(1,Math.ceil(Math.max(0,end-from)/86400000));return {days,current:days*Number(c.dailyRate||0),charge:c}}
